mapper.sql:
where 1=1

		and cpin_llave = #{llaveTabla}


		and cpin_estado = #{estado}


		and cpin_producto = #{producto}


		and cpin_bodega = #{bodega}


		and dpin_fechainicial >= #{fechaInicialMin}


		and dpin_fechainicial  <   #{fechaInicialMax}


		and ((select upper(movimiento_descripcion(cpro_documento)) from producto_prop where cpro_llave = cpin_producto) like upper('%'||#{filtroParametro}||'%'))
